import React from "react";

function MsgHistory({ datetime, email, msg }) {
  const headers = ["Date", "Message"];
  return (
    <table>
      <th className=" ">{headers.map((h)=>{
        return (<td>{h}</td>)
      })}</th>
    </table>
  );
}

export default MsgHistory;
